import"./chunk-ZW5NV4UO.js";var e={en:{title:"ESP32 and single-board computers on Mastodon: people and tags",description:"Find ESP32, Raspberry Pi and other board projects on Mastodon. Follow makers, board companies and useful hashtags, and preview their public posts.",heading:"ESP32 and single-board computers on Mastodon",listTitle:"ESP32 and single-board computers",intro:["From an ESP32 sensor to a Raspberry Pi project: discover people building with microcontrollers and single-board computers, alongside the companies and communities making the boards and their software.","Choose people and hashtags, then preview their public posts. Relevant tags stay available even with no posts: following and using the right tag helps a community grow."],faq:[{q:"Do I need an account?",a:"You can browse and preview public posts without an account. Sign in with your Mastodon account to follow people and hashtags or create a list."},{q:"Which boards and projects belong here?",a:"ESP32, ESP8266, Raspberry Pi, Pico, Arduino and other development boards belong here, along with firmware, MicroPython, CircuitPython and projects built around them. General technology, Linux or smart-home posts need a clear connection to board projects. Some tags are quiet and others contain unrelated posts or ads; preview them to choose your mix."},{q:"How do I get onto this list?",a:"Share board projects regularly and allow your server to suggest your profile. Recent activity, sustained topic fit and review determine the selection. For help or removal, contact @mawkingbird@mastodon.social."}]},de:{title:"ESP32 und Einplatinencomputer auf Mastodon: Wem folgen?",description:"Entdecke ESP32, Raspberry Pi und andere Boards auf Mastodon. Folge Menschen mit eigenen Projekten, Herstellern und passenden Hashtags.",heading:"ESP32 und Einplatinencomputer auf Mastodon",listTitle:"ESP32 und Einplatinencomputer",intro:["Ein Sensor mit ESP32, ein Projekt mit Raspberry Pi oder eigene Firmware: Hier findest du Menschen, die mit Mikrocontrollern und Einplatinencomputern bauen, sowie Hersteller und Communitys rund um die Boards.","W\xE4hle Menschen und Hashtags aus und schau dir ihre \xF6ffentlichen Beitr\xE4ge in der Vorschau an. Passende Hashtags bleiben auch ohne Beitr\xE4ge dabei. Wenn du ihnen folgst und sie selbst verwendest, kann daraus eine Community wachsen."],faq:[{q:"Brauche ich ein Konto?",a:"Zum St\xF6bern und f\xFCr die Vorschau \xF6ffentlicher Beitr\xE4ge brauchst du kein Konto. Um Menschen und Hashtags zu folgen oder eine Liste anzulegen, meldest du dich mit deinem Mastodon-Konto an."},{q:"Welche Boards und Projekte geh\xF6ren dazu?",a:"ESP32, ESP8266, Raspberry Pi, Pico, Arduino und weitere Entwicklungsboards sind dabei, ebenso Firmware, MicroPython, CircuitPython und Projekte damit. Allgemeine Technik, Linux und Smart Home geh\xF6ren nur mit klarem Bezug zu solchen Boards dazu. Unter manchen Hashtags ist wenig los, andere enthalten Werbung oder fremde Themen. Die Vorschau hilft dir bei der Auswahl."},{q:"Wie komme ich auf diese Liste?",a:"Schreib regelm\xE4\xDFig \xFCber deine Board-Projekte und erlaube deinem Server, dein Profil vorzuschlagen. Aktuelle Aktivit\xE4t, dauerhafter Themenbezug und die Pr\xFCfung z\xE4hlen. Bei Fragen oder f\xFCr eine Entfernung erreichst du @mawkingbird@mastodon.social."}]}};export{e as COPY};
